CREATE OR REPLACE FUNCTION public.fn_ca_club_data_fact_put(p_club uuid, p_day date, p_kind text, p_game uuid, p_user uuid, p_fee numeric, p_buyins numeric, p_cashouts numeric, p_winnings numeric, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE ok boolean:=true; d date; a timestamptz:=coalesce(p_at,now()); u uuid:=coalesce(p_user,'00000000-0000-0000-0000-000000000000');
BEGIN
 BEGIN
  PERFORM public.fn_ca_club_data_fact_put_pre_pacific(p_club,p_day,p_kind,p_game,p_user,p_fee,p_buyins,p_cashouts,p_winnings,p_at);
 EXCEPTION WHEN OTHERS THEN
  ok:=false;
  RAISE WARNING 'legacy Club Data projection: % %',SQLSTATE,SQLERRM;
 END;
 d:=public.fn_ca_club_data_pacific_day(a);
 BEGIN
 IF public.fn_ca_club_data_pacific_own('f:'||p_club||':'||p_day||':'||d||':'||p_game||':'||u||':'||ok) THEN
  INSERT INTO public.ca_club_data_pacific_fact AS f VALUES(p_club,p_day,d,p_kind,p_game,u,coalesce(p_fee,0),coalesce(p_buyins,0),coalesce(p_cashouts,0),coalesce(p_winnings,0),a,0,ok,CASE WHEN p_kind='CASH' AND p_fee>0 THEN 1 ELSE 0 END)
  ON CONFLICT(club_id,stat_date,game_id,user_id,utc_day,src,legacy_recorded) DO UPDATE SET
   fee=f.fee+EXCLUDED.fee,buyins=f.buyins+EXCLUDED.buyins,cashouts=f.cashouts+EXCLUDED.cashouts,winnings=f.winnings+EXCLUDED.winnings,last_at=greatest(f.last_at,EXCLUDED.last_at),hands=f.hands+EXCLUDED.hands;
 ELSE
  INSERT INTO public.ca_club_data_pacific_journal VALUES(p_club,p_day,d,p_kind,p_game,u,coalesce(p_fee,0),coalesce(p_buyins,0),coalesce(p_cashouts,0),coalesce(p_winnings,0),a,0,ok,CASE WHEN p_kind='CASH' AND p_fee>0 THEN 1 ELSE 0 END);
 END IF;
 EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.ca_club_data_pacific_failures(club_id,utc_day,source,detail) VALUES(p_club,p_day,'live_fact',SQLSTATE||':'||SQLERRM);
  RAISE WARNING 'Pacific Club Data projection: % %',SQLSTATE,SQLERRM;
 END;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_club_data_hand_put(p_club uuid, p_table uuid, p_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE d date:=public.fn_ca_club_data_pacific_day(p_at); u date:=(p_at AT TIME ZONE 'UTC')::date;
BEGIN
 BEGIN PERFORM public.fn_ca_club_data_hand_put_pre_pacific(p_club,p_table,p_at);
 EXCEPTION WHEN OTHERS THEN RAISE WARNING 'legacy hand projection: % %',SQLSTATE,SQLERRM; END;
 IF p_club IS NULL OR p_table IS NULL OR p_at IS NULL THEN RETURN; END IF;
 BEGIN
 IF public.fn_ca_club_data_pacific_own('h:'||p_club||':'||u||':'||d||':'||p_table) THEN
  INSERT INTO public.ca_club_data_pacific_hands AS h VALUES(p_club,u,d,p_table,1,0)
  ON CONFLICT(club_id,stat_date,table_id,utc_day,src) DO UPDATE SET hands=h.hands+1;
 ELSE INSERT INTO public.ca_club_data_pacific_hands_journal VALUES(p_club,u,d,p_table,1,0);
 END IF;
 EXCEPTION WHEN OTHERS THEN
  INSERT INTO public.ca_club_data_pacific_failures(club_id,utc_day,source,detail) VALUES(p_club,u,'live_hand',SQLSTATE||':'||SQLERRM);
  RAISE WARNING 'Pacific hand projection: % %',SQLSTATE,SQLERRM;
 END;
END $function$

CREATE OR REPLACE FUNCTION public.fn_ca_club_data_pacific_require(p_club uuid, p_from date, p_to date, p_max_days integer DEFAULT 93)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE a date:=coalesce(p_from,public.fn_ca_club_data_pacific_day(now())); b date:=least(coalesce(p_to,public.fn_ca_club_data_pacific_day(now())),public.fn_ca_club_data_pacific_day(now()));
BEGIN
 IF public.fn_ca_club_data_scope(p_club) IS NULL THEN RAISE EXCEPTION 'not authorized for this club' USING ERRCODE='42501'; END IF;
 IF a>b OR p_max_days NOT BETWEEN 1 AND 731 OR b-a>=p_max_days THEN RAISE EXCEPTION 'invalid_range'; END IF;
 IF a<(SELECT facts_from FROM public.ca_club_data_pacific_state)
 OR EXISTS(SELECT 1 FROM generate_series(a,least(b+1,(SELECT history_through FROM public.ca_club_data_pacific_state)),interval '1 day') d WHERE NOT EXISTS(SELECT 1 FROM public.ca_club_data_pacific_seed_log l WHERE l.utc_day=d::date))
 OR EXISTS(SELECT 1 FROM public.ca_club_data_pacific_failures f WHERE f.utc_day BETWEEN a AND b+1 AND (f.club_id IS NULL OR f.club_id=ANY(public.fn_ca_club_data_clubs(p_club)))) THEN
  RAISE EXCEPTION 'CLUB_DATA_PACIFIC_WINDOW_INCOMPLETE: original source history is unavailable or has not reconciled for this Pacific window';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_acct_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '50ms'
AS $function$
BEGIN
  PERFORM public.fn_ca_club_acct_put(public.fn_ca_club_acct_admission_rows(
    (SELECT jsonb_agg(to_jsonb(n)) FROM new_rows n)), 0::smallint);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    PERFORM public.fn_ca_club_acct_fail('cash_fee_admission',
      public.fn_ca_club_acct_day_of_sources(ARRAY(SELECT n.source_id FROM new_rows n)),
      SQLSTATE || ' ' || SQLERRM || ' sources=' || COALESCE((SELECT string_agg(n.source_id::text, ',') FROM new_rows n), ''));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'club data accounting projection could not record its failure: % %', SQLSTATE, SQLERRM;
  END;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_acct_cash_fee()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET lock_timeout TO '50ms'
AS $function$
BEGIN
  PERFORM public.fn_ca_club_acct_put(public.fn_ca_club_acct_cash_fee_rows(
    (SELECT jsonb_agg(to_jsonb(n)) FROM new_rows n)), 0::smallint);
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  BEGIN
    PERFORM public.fn_ca_club_acct_fail('cash_fee', (SELECT public.fn_ca_club_acct_safe_day(min(n.earned_at)) FROM new_rows n),
      SQLSTATE || ' ' || SQLERRM || ' ids=' || COALESCE((SELECT string_agg(n.id::text, ',') FROM new_rows n), ''));
  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'club data accounting projection could not record its failure: % %', SQLSTATE, SQLERRM;
  END;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_data_fact_rake()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_day date; v_union uuid; v_table_club uuid; v_tourn uuid; v_found boolean;
  v_uid uuid; v_club uuid; v_n numeric; r record; v_any boolean := false;
  v_hand_clubs uuid[] := ARRAY[]::uuid[];
BEGIN
  IF NEW.created_at < public.fn_ca_club_data_fact_live_from() THEN RETURN NULL; END IF;
  IF COALESCE(NEW.rake_amount, 0) = 0 THEN RETURN NULL; END IF;
  v_day := (NEW.created_at AT TIME ZONE 'UTC')::date;

  IF NEW.tournament_id IS NULL AND NOT COALESCE(NEW.is_tournament, false) THEN
    -- A cash hand: each contributor's share, to the club their seat was bought in through.
    IF NEW.table_id IS NULL OR NEW.rake_amount <= 0 THEN RETURN NULL; END IF;
    SELECT t.union_id, t.club_id, t.tournament_id, true
      INTO v_union, v_table_club, v_tourn, v_found
      FROM public.tables t WHERE t.id = NEW.table_id;
    IF v_found IS NOT TRUE OR v_tourn IS NOT NULL THEN RETURN NULL; END IF;
    FOR r IN
      WITH e AS (
        SELECT x.key::uuid AS uid, (CASE WHEN x.value ~ '^[0-9]+(\.[0-9]+)?$' THEN x.value::numeric ELSE 0 END) AS contrib
          FROM jsonb_each_text(CASE WHEN jsonb_typeof(NEW.player_contributions) = 'object'
                                    THEN NEW.player_contributions ELSE '{}'::jsonb END) x
         WHERE x.key ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
           AND (CASE WHEN x.value ~ '^[0-9]+(\.[0-9]+)?$' THEN x.value::numeric ELSE 0 END) > 0
      ), s AS (SELECT e.uid, e.contrib, SUM(e.contrib) OVER () AS tot FROM e)
      SELECT COALESCE(public.fn_ca_cash_seat_club(NEW.table_id, s.uid),
                      public.fn_ca_cash_reporting_club(v_union, v_table_club, s.uid)) AS club_id,
             s.uid, NEW.rake_amount * s.contrib / s.tot AS fee
        FROM s ORDER BY 1, 2
    LOOP
      v_any := true;
      CONTINUE WHEN r.club_id IS NULL;
      CONTINUE WHEN public.fn_ca_launch_accounting_accepts(r.club_id, NEW.created_at) IS NOT TRUE;
      PERFORM public.fn_ca_club_data_fact_put(r.club_id, v_day, 'CASH', NEW.table_id, r.uid,
                                              r.fee, 0, 0, 0, NEW.created_at);
      IF NOT (r.club_id = ANY (v_hand_clubs)) THEN
        v_hand_clubs := v_hand_clubs || r.club_id;
        PERFORM public.fn_ca_club_data_hand_put(r.club_id, NEW.table_id, NEW.created_at);
      END IF;
    END LOOP;
    -- A raked hand that named nobody is the table's club's rake, whole.
    IF NOT v_any AND v_table_club IS NOT NULL
       AND public.fn_ca_launch_accounting_accepts(v_table_club, NEW.created_at) IS TRUE THEN
      PERFORM public.fn_ca_club_data_fact_put(v_table_club, v_day, 'CASH', NEW.table_id, NULL,
                                              NEW.rake_amount, 0, 0, 0, NEW.created_at);
      PERFORM public.fn_ca_club_data_hand_put(v_table_club, NEW.table_id, NEW.created_at);
    END IF;
    RETURN NULL;
  END IF;

  -- A tournament fee: the named player's entry club, else split across the entries.
  IF NEW.tournament_id IS NULL THEN RETURN NULL; END IF;
  SELECT tr.union_id, tr.club_id INTO v_union, v_table_club
    FROM public.tournaments tr WHERE tr.id = NEW.tournament_id;
  IF NEW.metadata ? 'user_id'
     AND (NEW.metadata->>'user_id') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' THEN
    v_uid := (NEW.metadata->>'user_id')::uuid;
    SELECT tp.club_id INTO v_club FROM public.tournament_players tp
     WHERE tp.tournament_id = NEW.tournament_id AND tp.user_id = v_uid;
    v_club := COALESCE(v_club, public.fn_ca_cash_reporting_club(v_union, v_table_club, v_uid));
    IF v_club IS NOT NULL AND public.fn_ca_launch_accounting_accepts(v_club, NEW.created_at) IS TRUE THEN
      PERFORM public.fn_ca_club_data_fact_put(v_club, v_day, 'TOURNAMENT', NEW.tournament_id, v_uid,
                                              NEW.rake_amount, 0, 0, 0, NEW.created_at);
    END IF;
  ELSE
    SELECT count(*)::numeric INTO v_n FROM public.tournament_players tp
     WHERE tp.tournament_id = NEW.tournament_id;
    IF COALESCE(v_n, 0) = 0 THEN RETURN NULL; END IF;
    FOR r IN
      SELECT COALESCE(tp.club_id, public.fn_ca_cash_reporting_club(v_union, v_table_club, tp.user_id)) AS club_id,
             tp.user_id
        FROM public.tournament_players tp
       WHERE tp.tournament_id = NEW.tournament_id
       ORDER BY 1, 2
    LOOP
      CONTINUE WHEN r.club_id IS NULL;
      CONTINUE WHEN public.fn_ca_launch_accounting_accepts(r.club_id, NEW.created_at) IS NOT TRUE;
      PERFORM public.fn_ca_club_data_fact_put(r.club_id, v_day, 'TOURNAMENT', NEW.tournament_id, r.user_id,
                                              NEW.rake_amount / v_n, 0, 0, 0, NEW.created_at);
    END LOOP;
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'Club Data fact (rake) failed for row %: %', NEW.id, SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_ca_club_rake_daily_user_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_ids uuid[];
BEGIN
  SELECT array_agg(n.id) INTO v_ids
    FROM new_rows n
   WHERE n.club_id IS NOT NULL AND n.player_id IS NOT NULL AND n.rake_amount > 0;
  IF v_ids IS NOT NULL THEN
    PERFORM public.fn_ca_club_rake_daily_user_apply(v_ids);
  END IF;
  RETURN NULL;
EXCEPTION WHEN OTHERS THEN
  -- Never fail a raked hand for a reporting table.
  RAISE WARNING 'ca_club_rake_daily_user insert rollup failed: %', SQLERRM;
  RETURN NULL;
END;
$function$
